-- Series FM-30 (metal-seated multi-port 3/4-way, quote-only Price NULL). Run from file (SSMS). Self-cleaning on re-run.
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series FM-30')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, Approvals, KeyFeatures)
    VALUES (N'Series FM-30', N'The Mars Series FM-30 is a 3-way/4-way metal-seated multi-port ball valve rated ANSI Class 150/300 and PN10/40, full or reduced port, in sizes 1/2" to 6". CF8M or WCB body with SS316+Stellite seats, a CF8M+hard-chrome ball and a 17-4PH stem, in threaded, butt-weld, socket-weld or flanged ends. Tungsten-carbide, chrome-carbide or full-Stellite ball & seats available on request.', N'CF8M / WCB', N'SS316 + Stellite', N'Three/Four-Way, Metal Seated, Full & Reduced Port', NULL, N'3-way / 4-way metal seated multi-port design
Full port & reduced port
Pressure: ANSI #150/#300, PN10/40
Ends: Threaded, Butt Weld, Socket Weld, Flanged
Body: CF8M, WCB
Seats: SS316 + Stellite (standard)
Ball: CF8M + Hard Chrome
Stem: 17-4PH
Options on request: Tungsten carbide, Chrome carbide, or Stellite ball & seats
Size 1/2" to 6"');

DECLARE @SeriesName nvarchar(100) = N'Series FM-30';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

-- Idempotent: clear any prior rows for this series so re-running always yields a clean set.
DELETE FROM ProductFilterValues WHERE CategoryId = @CategoryId;
DELETE FROM CatalogProducts WHERE CategoryId = @CategoryId;
DELETE FROM CategoryFilters WHERE CategoryId = @CategoryId;

INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Ball Configuration'),(N'Ends'),(N'Size'),(N'Port')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);

INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'Ball Configuration',0),(N'Ends',1),(N'Size',2),(N'Port',3)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

